    let currentLanguage = 'zh';

    function getLanguage() { return currentLanguage; }

    // 按 key 取当前语言文本，{param} 插值
    function t(key, params) {
      let s = (I18N[currentLanguage] || I18N.zh)[key] ?? I18N.zh[key] ?? key;
      if (params) {
        for (const k in params) {
          s = s.split('{' + k + '}').join(String(params[k]));
        }
      }
      return s;
    }

    // 替换元素文本：纯文本元素整体替换；含子元素（如 svg 图标+文字）时只替换非 svg 文本节点
    function applyI18nText(el, key) {
      const value = t(key);
      if (!el.children.length) { el.textContent = value; return; }
      const nodes = [];
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
        acceptNode(n) {
          if (n.parentElement.closest('svg')) return NodeFilter.FILTER_REJECT;
          if (n.nodeValue.trim() === '') return NodeFilter.FILTER_REJECT;
          return NodeFilter.FILTER_ACCEPT;
        }
      });
      while (walker.nextNode()) nodes.push(walker.currentNode);
      if (nodes.length) {
        nodes.forEach((n, i) => { n.nodeValue = i === 0 ? value : ''; });
      }
    }

    function applyStaticTranslations() {
      document.querySelectorAll('[data-i18n]').forEach(el => {
        applyI18nText(el, el.dataset.i18n);
      });
      document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.setAttribute('placeholder', t(el.dataset.i18nPlaceholder));
      });
      document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.setAttribute('title', t(el.dataset.i18nTitle));
      });
    }

    function setLanguage(lang) {
      currentLanguage = lang === 'en' ? 'en' : 'zh';
      document.documentElement.lang = currentLanguage === 'zh' ? 'zh-CN' : 'en';
      document.title = t('app.title');
      applyStaticTranslations();
      // 同步语言滑块状态（HTML 硬编码 .on，需随当前语言校正）
      const langBtn = document.getElementById('btnToggleLang');
      if (langBtn) {
        langBtn.classList.toggle('on', currentLanguage === 'zh');
        langBtn.setAttribute('aria-checked', String(currentLanguage === 'zh'));
      }
    }
